typedef __int128 L;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        long long a0; int n; scanf("%lld %d",&a0,&n);
        vector<int> d(n); bool has[10]={0};
        for(auto&x:d){scanf("%d",&x);has[x]=1;}
        string A=to_string(a0); int len=A.size(); L a=a0, best=-1;
        auto con=[&](L b){ L df=b>a?b-a:a-b; if(best<0||df<best) best=df; };
        auto fill=[&](L v,int dig,int c){ while(c--) v=v*10+dig; return v; };
        int mn=d[0], mx=d[n-1], nz=-1;
        for(int x:d) if(x>0){nz=x;break;}
        if(has[0]) con(0);
        L cur=0; bool full=true;
        for(int p=0;p<len;p++){
            int x=A[p]-'0';
            for(int y=x-1;y>=0;y--) if(has[y] && !(p==0&&len>1&&y==0)){ con(fill(cur*10+y,mx,len-p-1)); break; }
            for(int y=x+1;y<=9;y++) if(has[y]){ con(fill(cur*10+y,mn,len-p-1)); break; }
            if(!has[x]){full=false;break;}
            cur=cur*10+x;
        }
        if(full) con(a);
        if(len>1 && mx>0) con(fill(0,mx,len-1));
        if(nz>0) con(fill(nz,mn,len));
        printf("%llu\n",(unsigned long long)best);
    }
}

