#include <bits/stdc++.h>
using namespace std;
typedef long long ll; const ll M=998244353;
ll pw(ll b,ll e){ll r=1;b%=M;while(e){if(e&1)r=r*b%M;b=b*b%M;e>>=1;}return r;}
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n); vector<ll> a(n),b(n);
        for(auto&x:a) scanf("%lld",&x);
        for(auto&x:b) scanf("%lld",&x);
        if(n==1){puts("0");continue;}
        vector<pair<int,int>> R; R.reserve((size_t)n*(n-1));
        for(int p=0;p<n;p++) for(int q=0;q<n;q++) if(p!=q) R.push_back({(int)b[p],(int)b[q]});
        auto lt=[](const pair<int,int>&x,const pair<int,int>&y){return (ll)x.first*y.second<(ll)y.first*x.second;};
        sort(R.begin(),R.end(),lt);
        ll tot=0;
        for(int i=0;i<n;i++) for(int j=i+1;j<n;j++){
            pair<int,int> f={(int)a[j],(int)a[i]};
            tot+= R.end()-upper_bound(R.begin(),R.end(),f,lt);
        }
        printf("%lld\n", tot%M*pw((ll)n*(n-1)%M,M-2)%M);
    }
}

